const test = require('node:test');
const assert = require('node:assert/strict');
const {spawnSync} = require('node:child_process');
test('remaining preservation regressions retain task state and report image changes without preview-dependent cleanup', () => {
  const environment = {...process.env};
  delete environment.NODE_TEST_CONTEXT;
  const result = spawnSync(process.execPath, ['--test','--test-reporter=tap','--test-name-pattern=parent regression','scripts/ci/ui_preservation.test.cjs'], {
    cwd: '/Users/jon/projects/scrypath/.claude/worktrees/agent-p185-glue-u80ewc0s', env:environment,encoding:'utf8',timeout:30000,maxBuffer:4*1024*1024
  });
  assert.ifError(result.error);
  assert.match(result.stdout,/# tests 3\b/);
  assert.equal(result.status,0,result.stdout+result.stderr);
});
